flow.t:
Corefile: |
  .:53 {
      errors
      health {
         lameduck 5s
      }
      ready
      rewrite name api.example.com backend-svc.web.svc.cluster.local   # <-- CHANGE
      kubernetes cluster.local in-addr.arpa ip6.arpa {

cat <<'EOF' | kubectl apply -f -
apiVersion: v1
kind: Service
metadata: {name: front-end-svc, namespace: front}
spec:
  type: NodePort
  selector: {app: front-end}
  ports:
  - {name: http, port: 80, targetPort: http, protocol: TCP, nodePort: 30080}
EOF

