kubectl create namespace nginx-static --dry-run=client -o yaml | kubectl apply -f -
openssl req -x509 -nodes -newkey rsa:2048 -days 365 -subj "/CN=web.example.com" -keyout /tmp/nginx-tls.key -out /tmp/nginx-tls.crt 2>/dev/null
kubectl -n nginx-static create secret tls nginx-tls --cert=/tmp/nginx-tls.crt --key=/tmp/nginx-tls.key --dry-run=client -o yaml | kubectl apply -f -
kubectl -n nginx-static get cm nginx-config -o jsonpath='{.immutable}' 2>/dev/null | grep -q true && kubectl -n nginx-static delete cm nginx-config
cat <<'EOF' | kubectl apply -f -
apiVersion: v1
kind: ConfigMap
metadata: {name: nginx-config, namespace: nginx-static}
data:
  nginx.conf: |
    events {}
    http {
      server {
        listen 443 ssl;
        server_name web.example.com;
        ssl_certificate /etc/nginx/tls/tls.crt;
        ssl_certificate_key /etc/nginx/tls/tls.key;
        ssl_protocols TLSv1.2 TLSv1.3;
        location / { return 200 "ok\n"; }
      }
    }
---
apiVersion: apps/v1
kind: Deployment
metadata: {name: nginx-static, namespace: nginx-static}
spec:
  selector: {matchLabels: {app: nginx-static}}
  template:
    metadata: {labels: {app: nginx-static}}
    spec:
      containers:
      - name: nginx
        image: nginx:1.27-alpine
        volumeMounts:
        - {name: conf, mountPath: /etc/nginx/nginx.conf, subPath: nginx.conf}
        - {name: tls, mountPath: /etc/nginx/tls}
      volumes:
      - {name: conf, configMap: {name: nginx-config}}
      - {name: tls, secret: {secretName: nginx-tls}}
---
apiVersion: v1
kind: Service
metadata: {name: nginx-static, namespace: nginx-static}
spec: {selector: {app: nginx-static}, ports: [{port: 443}]}
EOF

